package com.sumedha.commerce.user.entity; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="user_profiles") public class UserProfile { @Id @Column(name="profile_id") private UUID id; @Column(name="auth_user_id",nullable=false,unique=true) private UUID authUserId; @Column(name="first_name") private String firstName; @Column(name="last_name") private String lastName; private String phone; @Column(name="avatar_url") private String avatarUrl; @Column(name="date_of_birth") private LocalDate dateOfBirth; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected UserProfile(){} public UserProfile(UUID a,String f,String l,String p,String u,LocalDate d){id=UUID.randomUUID();authUserId=a;firstName=f;lastName=l;phone=p;avatarUrl=u;dateOfBirth=d;createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void touch(){updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getAuthUserId(){return authUserId;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public String getPhone(){return phone;} public String getAvatarUrl(){return avatarUrl;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void update(String f,String l,String p,String u,LocalDate d){firstName=f;lastName=l;phone=p;avatarUrl=u;dateOfBirth=d;} }
